using System;
using System.ComponentModel.DataAnnotations;

namespace TransactionProcessor.DataTransferObjects.Requests.Estate
{
    /// <summary>
    /// Display name used to create an estate. The estate identifier is generated by the service.
    /// </summary>
    /// <example>{"estateName":"Example Name"}</example>
    public class CreateEstateRequest
    {
        /// <summary>
        /// Display name for the estate.
        /// </summary>
        [Required]
        public String EstateName { get; set; }
    }
}
